mapper.select:
SELECT u.id AS user_id, u.username AS username, u.nickname AS nickname, d.dept_name AS dept_name, u.phone AS phone, r.read_time AS read_time FROM sys_notice_read r INNER JOIN sys_user u ON u.id = r.user_id AND u.deleted = 0 LEFT JOIN sys_dept d ON d.id = u.dept_id WHERE r.notice_id = #{noticeId}
AND ( u.username LIKE CONCAT('%', #{searchValue}, '%') OR u.nickname LIKE CONCAT('%', #{searchValue}, '%') )
ORDER BY r.read_time DESC
